css:
/* ============================================================
 * 初音未来主题 · miku.star
 * 作用域：html.yh-theme-miku-star
 * 设计：青葱水色 + 粉紫星光；侧栏贴左、顶栏玻璃、内容浮卡。
 * 壁纸 / 横幅 / 侧栏立绘通过 CSS 变量注入（data URI）。
 * ============================================================ */

/* ---------- 0. 调色板 + Flarum 变量重映射 ---------- */
html.yh-theme-miku-star {
	--mk-teal: #39c5bb;
	--mk-teal-deep: #1fa8a0;
	--mk-teal-soft: #7fe0d8;
	--mk-pink: #ff8ec8;
	--mk-pink-soft: #ffc2e0;
	--mk-lavender: #b8a6ff;
	--mk-sky: #a8e4ff;
	--mk-mint: #d4fff6;
	--mk-ink: #1a3a42;
	--mk-ink-soft: #3d5f68;
	--mk-muted: #6a8a92;
	--mk-glass: rgba(255, 255, 255, 0.72);
	--mk-glass-strong: rgba(255, 255, 255, 0.88);
	--mk-glass-edge: rgba(255, 255, 255, 0.55);
	--mk-shadow: 0 12px 40px rgba(57, 197, 187, 0.18), 0 2px 8px rgba(26, 58, 66, 0.08);
	--mk-radius: 16px;
	--mk-radius-sm: 10px;
	--mk-font: "Segoe UI", "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", sans-serif;
	--mk-side-w: 220px;
	--mk-header-h: 58px;
	--mk-banner-h: 168px;

	/* Flarum 设计令牌 → 初音色 */
	--primary-color: #39c5bb;
	--secondary-color: #ff8ec8;
	--body-bg: transparent;
	--body-bg-shaded: rgba(255, 255, 255, 0.55);
	--body-bg-light: rgba(255, 255, 255, 0.82);
	--body-bg-faded: rgba(255, 255, 255, 0.7);
	--text-color: #1a3a42;
	--heading-color: #146a66;
	--link-color: #1fa8a0;
	--muted-color: #6a8a92;
	--muted-color-light: #8aa8b0;
	--muted-more-color: #9bb4bb;
	--control-bg: rgba(255, 255, 255, 0.78);
	--control-bg-light: rgba(255, 255, 255, 0.92);
	--control-bg-shaded: rgba(57, 197, 187, 0.12);
	--control-color: #1a3a42;
	--shadow-color: rgba(57, 197, 187, 0.22);
	--header-bg: transparent;
	--header-color: #1a3a42;
	--header-colored-color: #1a3a42;
	--header-colored-control-color: #1a3a42;
	--header-colored-control-bg: rgba(255, 255, 255, 0.55);
	--header-colored-control-bg-shaded: rgba(255, 255, 255, 0.75);
	--header-colored-control-bg-fadedin: rgba(57, 197, 187, 0.18);
	--hero-bg: transparent;
	--hero-color: #146a66;
	--discussion-title-color: #146a66;
	--discussion-list-item-bg-hover: rgba(57, 197, 187, 0.12);
	--button-color: #1a3a42;
	--button-bg: rgba(255, 255, 255, 0.85);
	--button-bg-hover: #e8fffb;
	--button-bg-active: #d4fff6;
	--button-primary-color: #ffffff;
	--button-primary-bg: #39c5bb;
	--button-primary-bg-hover: #4fd4cb;
	--button-primary-bg-active: #1fa8a0;
	--overlay-bg: rgba(26, 58, 66, 0.42);
	--code-bg: rgba(212, 255, 246, 0.55);
	--code-color: #1a3a42;
	--border-radius: 12px;
	--zindex-header: 1000;
	/* 保留 Flarum 在 ModalManager / Modal-backdrop 间计算出的层级差。 */
	--zindex-modal: 1700;

	/* sticky 侧栏 / Scrubber 要落在玻璃顶栏下方 */
	--header-height: calc(var(--mk-header-h) + 12px);
	--header-height-phone: calc(var(--mk-header-h) + 8px);
}

/* ---------- 1. 页面底：壁纸 + 柔光 ---------- */
html.yh-theme-miku-star,
html.yh-theme-miku-star body {
	min-height: 100%;
}

html.yh-theme-miku-star body {
	font-family: var(--mk-font);
	color: var(--mk-ink);
	background:
		linear-gradient(
			105deg,
			rgba(232, 255, 251, 0.92) 0%,
			rgba(232, 255, 251, 0.78) 28%,
			rgba(255, 245, 252, 0.55) 52%,
			rgba(255, 255, 255, 0.22) 72%,
			rgba(255, 255, 255, 0.08) 100%
		),
		var(--mk-bg, linear-gradient(135deg, #d4fff6, #e8f7ff 45%, #ffe8f5));
	background-attachment: fixed;
	background-size: cover;
	background-position: right center;
	background-repeat: no-repeat;
	overflow-x: hidden;
}

/* 左侧再铺一层淡星光，避免文字区被立绘抢对比度 */
html.yh-theme-miku-star body::before {
	content: "";
	position: fixed;
	inset: 0;
	z-index: 0;
	pointer-events: none;
	background:
		radial-gradient(ellipse 50% 40% at 12% 18%, rgba(127, 224, 216, 0.35), transparent 70%),
		radial-gradient(ellipse 40% 35% at 88% 12%, rgba(255, 142, 200, 0.18), transparent 65%),
		radial-gradient(ellipse 35% 30% at 70% 80%, rgba(184, 166, 255, 0.16), transparent 70%);
}

html.yh-theme-miku-star #app.App {
	position: relative;
	z-index: 1;
	min-height: 100vh;
	background: transparent !important;
}

/* ---------- 2. 顶栏：贴顶玻璃条 + 横幅纹理 ---------- */
html.yh-theme-miku-star #app-navigation {
	display: none !important;
}

html.yh-theme-miku-star .App-drawer {
	position: static !important;
	width: auto !important;
	transform: none !important;
	visibility: visible !important;
	background: transparent !important;
	box-shadow: none !important;
	z-index: auto !important;
}

html.yh-theme-miku-star .App-header {
	position: fixed !important;
	top: 0 !important;
	left: 0 !important;
	right: 0 !important;
	z-index: 1200 !important;
	height: var(--mk-header-h) !important;
	padding: 0 !important;
	border: 0 !important;
	box-sizing: border-box;
	background:
		linear-gradient(90deg, rgba(255, 255, 255, 0.88) 0%, rgba(232, 255, 251, 0.78) 42%, rgba(255, 255, 255, 0.55) 100%),
		var(--mk-top, none) !important;
	background-size: auto, auto 180% !important;
	background-position: 0 0, right -20% center !important;
	background-repeat: no-repeat !important;
	backdrop-filter: blur(16px) saturate(1.25);
	-webkit-backdrop-filter: blur(16px) saturate(1.25);
	box-shadow:
		0 1px 0 rgba(255, 255, 255, 0.7),
		0 8px 28px rgba(57, 197, 187, 0.14) !important;
	color: var(--mk-ink) !important;
}

html.yh-theme-miku-star .App-header::after {
	content: "";
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	height: 2px;
	background: linear-gradient(90deg, var(--mk-teal), var(--mk-pink), var(--mk-lavender), var(--mk-teal-soft));
	opacity: 0.85;
	pointer-events: none;
}

html.yh-theme-miku-star .App-header .container {
	width: auto !important;
	max-width: none !important;
	height: 100%;
	padding: 0 18px 0 calc(var(--mk-side-w) + 18px) !important;
	display: flex !important;
	align-items: center;
	gap: 12px;
	flex-wrap: nowrap;
	overflow: visible;
}

html.yh-theme-miku-star .Header-title {
	float: none !important;
	margin: 0 10px 0 0 !important;
	padding: 0 !important;
	line-height: 1;
	font-weight: 700;
	letter-spacing: 0.02em;
}

html.yh-theme-miku-star .Header-title a {
	color: var(--mk-teal-deep) !important;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.8);
}

html.yh-theme-miku-star .Header-logo {
	max-height: 28px;
	filter: drop-shadow(0 1px 2px rgba(57, 197, 187, 0.35));
}

html.yh-theme-miku-star .Header-primary {
	float: none !important;
	flex: 1 1 auto;
	min-width: 0;
}

html.yh-theme-miku-star .Header-secondary {
	float: none !important;
	margin-left: auto;
}

html.yh-theme-miku-star .App-header a,
html.yh-theme-miku-star .App-header .Button {
	color: var(--mk-ink) !important;
	text-shadow: none !important;
}

html.yh-theme-miku-star .Header-controls {
	display: flex;
	align-items: center;
	gap: 4px;
	margin: 0;
	padding: 0;
	list-style: none;
}

html.yh-theme-miku-star .Header-controls > li {
	padding: 0 2px;
	float: none !important;
}

/* ---------- 3. 侧栏：贴最左边，全高玻璃 + 立绘 ---------- */
html.yh-theme-miku-star .App-content {
	min-height: 0 !important;
	height: auto !important;
	margin: 0 !important;
	padding: calc(var(--mk-header-h) + 18px) 20px 40px calc(var(--mk-side-w) + 24px) !important;
	border: 0 !important;
	background: transparent !important;
	box-shadow: none !important;
}

html.yh-theme-miku-star .App-content > .container,
html.yh-theme-miku-star .App-content .container {
	max-width: 1120px !important;
	padding-left: 0 !important;
	padding-right: 0 !important;
}

/* 首页 Hero 变成横幅卡 */
html.yh-theme-miku-star .Hero,
html.yh-theme-miku-star .WelcomeHero {
	position: relative;
	margin: 0 0 20px !important;
	padding: 0 !important;
	min-height: var(--mk-banner-h);
	border-radius: var(--mk-radius);
	overflow: hidden;
	border: 1px solid var(--mk-glass-edge);
	box-shadow: var(--mk-shadow);
	background:
		linear-gradient(100deg, rgba(255, 255, 255, 0.82) 0%, rgba(232, 255, 251, 0.55) 38%, rgba(255, 255, 255, 0.18) 100%),
		var(--mk-top, linear-gradient(120deg, #d4fff6, #ffe8f5)) !important;
	background-size: auto, cover !important;
	background-position: 0 0, left center !important;
	background-repeat: no-repeat !important;
	color: var(--mk-ink) !important;
}

html.yh-theme-miku-star .Hero .container {
	position: relative;
	z-index: 1;
	padding: 28px 32px !important;
	max-width: none !important;
}

html.yh-theme-miku-star .Hero h1,
html.yh-theme-miku-star .Hero-title {
	color: var(--mk-teal-deep) !important;
	font-weight: 800 !important;
	letter-spacing: 0.02em;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.85), 0 8px 24px rgba(57, 197, 187, 0.25);
	margin: 0 0 8px !important;
}

html.yh-theme-miku-star .Hero-subtitle {
	color: var(--mk-ink-soft) !important;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.7);
	max-width: 36em;
}

/* 侧栏贴左：fixed 全高 */
html.yh-theme-miku-star .sideNavContainer {
	display: block !important;
	position: relative;
}

html.yh-theme-miku-star .sideNav,
html.yh-theme-miku-star .IndexPage-nav.sideNav,
html.yh-theme-miku-star .DiscussionPage-nav {
	position: fixed !important;
	top: var(--mk-header-h) !important;
	left: 0 !important;
	bottom: 0 !important;
	width: var(--mk-side-w) !important;
	min-width: var(--mk-side-w) !important;
	max-width: var(--mk-side-w) !important;
	margin: 0 !important;
	padding: 18px 14px 360px !important;
	z-index: 1100 !important;
	float: none !important;
	overflow-x: hidden !important;
	overflow-y: auto !important;
	white-space: normal !important;
	box-sizing: border-box;
	isolation: isolate;
	background:
		linear-gradient(180deg, rgba(255, 255, 255, 0.82) 0%, rgba(232, 255, 251, 0.72) 55%, rgba(255, 240, 250, 0.55) 100%),
		linear-gradient(180deg, rgba(232, 255, 251, 0) 0%, rgba(232, 255, 251, 0.72) 100%),
		var(--mk-nav, none) !important;
	background-size: auto, auto, auto 360px !important;
	background-position: 0 0, 0 0, 52% bottom !important;
	background-repeat: no-repeat !important;
	backdrop-filter: blur(18px) saturate(1.2);
	-webkit-backdrop-filter: blur(18px) saturate(1.2);
	border: 0 !important;
	border-right: 1px solid rgba(57, 197, 187, 0.22) !important;
	box-shadow: 8px 0 32px rgba(57, 197, 187, 0.1) !important;
}

/* 侧栏底部立绘 */
html.yh-theme-miku-star .sideNav::after,
html.yh-theme-miku-star .IndexPage-nav.sideNav::after,
html.yh-theme-miku-star .DiscussionPage-nav::after {
	display: none !important;
}

html.yh-theme-miku-star .sideNav > ul,
html.yh-theme-miku-star .sideNav > ul.affix {
	width: 100% !important;
	margin: 0 !important;
	padding: 0 !important;
	position: static !important;
	top: auto !important;
	list-style: none;
}

html.yh-theme-miku-star .sideNav > ul > li,
html.yh-theme-miku-star .sideNav .Dropdown-menu > li {
	display: block !important;
	margin: 0 0 8px !important;
	width: 100% !important;
	float: none !important;
}

html.yh-theme-miku-star .sideNav .Dropdown--select {
	display: block !important;
	width: 100%;
}

html.yh-theme-miku-star .sideNav .Dropdown--select .Dropdown-toggle {
	display: none !important;
}

html.yh-theme-miku-star .sideNav .Dropdown--select .Dropdown-menu {
	display: block !important;
	position: static !important;
	float: none !important;
	width: 100% !important;
	min-width: 0 !important;
	margin: 0 !important;
	padding: 0 !important;
	border: 0 !important;
	background: transparent !important;
	box-shadow: none !important;
}

html.yh-theme-miku-star .sideNav .Dropdown-menu > li > a,
html.yh-theme-miku-star .sideNav .Dropdown--select .Dropdown-menu > li > a {
	display: block !important;
	padding: 10px 12px 10px 14px !important;
	border-radius: 999px !important;
	color: var(--mk-ink-soft) !important;
	font-weight: 600;
	transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

html.yh-theme-miku-star .sideNav .Dropdown-menu > li > a:hover,
html.yh-theme-miku-star .sideNav .Dropdown--select .Dropdown-menu > li > a:hover {
	background: rgba(57, 197, 187, 0.14) !important;
	color: var(--mk-teal-deep) !important;
	text-decoration: none !important;
	transform: translateX(2px);
}

html.yh-theme-miku-star .sideNav .Dropdown-menu > li.active > a,
html.yh-theme-miku-star .sideNav .Dropdown--select .Dropdown-menu > li.active > a {
	background: linear-gradient(90deg, rgba(57, 197, 187, 0.95), rgba(127, 224, 216, 0.92)) !important;
	color: #fff !important;
	font-weight: 700 !important;
	box-shadow: 0 6px 16px rgba(57, 197, 187, 0.28);
}

html.yh-theme-miku-star .item-newDiscussion .Button,
html.yh-theme-miku-star .sideNav .item-newDiscussion .Button {
	width: 100%;
	border-radius: 999px !important;
	font-weight: 700;
	letter-spacing: 0.04em;
	box-shadow: 0 8px 20px rgba(57, 197, 187, 0.3) !important;
}

html.yh-theme-miku-star .sideNavOffset,
html.yh-theme-miku-star .IndexPage-results.sideNavOffset,
html.yh-theme-miku-star .DiscussionPage-stream {
	margin: 0 !important;
	float: none !important;
	width: auto !important;
	flex: none !important;
	min-width: 0;
}

/* 讨论页右侧 Scrubber 也并入左栏语言 */
html.yh-theme-miku-star .DiscussionPage-discussion > .container {
	display: block !important;
	max-width: none !important;
	padding: 0 !important;
}

html.yh-theme-miku-star .DiscussionPage-nav > ul {
	padding: 0;
	margin: 0;
	list-style: none;
}

html.yh-theme-miku-star .DiscussionPage-nav .Scrubber a {
	color: var(--mk-teal-deep) !important;
	font-weight: 600;
}

html.yh-theme-miku-star .DiscussionPage-nav .Scrubber-scrollbar {
	background:
		linear-gradient(180deg, rgba(255, 255, 255, 0.7), rgba(212, 255, 246, 0.55)),
		repeating-linear-gradient(
			180deg,
			rgba(57, 197, 187, 0.08) 0 2px,
			transparent 2px 6px
		);
	border: 1px solid rgba(57, 197, 187, 0.25);
	border-radius: 999px;
	margin: 10px 0 !important;
	overflow: hidden;
}

html.yh-theme-miku-star .Scrubber-bar {
	background: linear-gradient(180deg, var(--mk-teal-soft), var(--mk-teal), var(--mk-pink)) !important;
	border-radius: 999px;
	box-shadow: 0 0 12px rgba(57, 197, 187, 0.45);
}

html.yh-theme-miku-star .Scrubber-handle {
	color: var(--mk-teal-deep);
}

/* ---------- 4. 内容浮卡 ---------- */
html.yh-theme-miku-star .IndexPage-toolbar {
	display: flex;
	align-items: center;
	gap: 10px;
	margin: 0 0 14px;
	padding: 10px 14px;
	list-style: none;
	background: var(--mk-glass);
	border: 1px solid var(--mk-glass-edge);
	border-radius: var(--mk-radius-sm);
	backdrop-filter: blur(10px);
	-webkit-backdrop-filter: blur(10px);
	box-shadow: 0 4px 16px rgba(57, 197, 187, 0.08);
}

html.yh-theme-miku-star .DiscussionList-discussions {
	list-style: none;
	margin: 0;
	padding: 8px;
	border: 1px solid var(--mk-glass-edge);
	border-radius: var(--mk-radius);
	background: var(--mk-glass-strong);
	backdrop-filter: blur(12px);
	-webkit-backdrop-filter: blur(12px);
	box-shadow: var(--mk-shadow);
	overflow: hidden;
}

html.yh-theme-miku-star .DiscussionListItem {
	border: 0;
	border-bottom: 1px solid rgba(57, 197, 187, 0.1);
	border-radius: 12px;
	margin: 0 0 4px;
	transition: background 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}

html.yh-theme-miku-star .DiscussionListItem:last-child {
	border-bottom: 0;
	margin-bottom: 0;
}

html.yh-theme-miku-star .DiscussionListItem:hover {
	background: linear-gradient(90deg, rgba(57, 197, 187, 0.1), rgba(255, 142, 200, 0.08));
	transform: translateY(-1px);
	box-shadow: 0 8px 20px rgba(57, 197, 187, 0.12);
}

html.yh-theme-miku-star .DiscussionListItem:nth-child(even) {
	background: rgba(232, 255, 251, 0.35);
}

html.yh-theme-miku-star .DiscussionListItem:nth-child(even):hover {
	background: linear-gradient(90deg, rgba(57, 197, 187, 0.12), rgba(255, 142, 200, 0.1));
}

html.yh-theme-miku-star .DiscussionListItem-title {
	color: var(--mk-teal-deep) !important;
	font-weight: 700;
}

html.yh-theme-miku-star .DiscussionListItem-title:hover {
	color: var(--mk-pink) !important;
	text-decoration: none;
}

html.yh-theme-miku-star .DiscussionListItem-count {
	background: linear-gradient(180deg, var(--mk-teal-soft), var(--mk-teal));
	color: #fff !important;
	border-radius: 999px;
	min-width: 28px;
	padding: 2px 8px;
	font-weight: 700;
	box-shadow: 0 4px 10px rgba(57, 197, 187, 0.28);
}

html.yh-theme-miku-star .Avatar {
	border-radius: 50% !important;
	box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.9), 0 0 0 4px rgba(57, 197, 187, 0.35);
}

html.yh-theme-miku-star .Avatar img {
	border-radius: 50% !important;
}

html.yh-theme-miku-star .Badge,
html.yh-theme-miku-star .TagLabel {
	border-radius: 999px !important;
	box-shadow: 0 2px 6px rgba(57, 197, 187, 0.15);
}

html.yh-theme-miku-star .DiscussionHero {
	margin: 0 0 16px !important;
	padding: 16px 20px !important;
	border-radius: var(--mk-radius);
	border: 1px solid var(--mk-glass-edge);
	background:
		linear-gradient(120deg, rgba(255, 255, 255, 0.9), rgba(232, 255, 251, 0.75) 55%, rgba(255, 232, 245, 0.55)),
		var(--mk-top, none) !important;
	background-size: auto, cover !important;
	background-position: 0 0, right center !important;
	box-shadow: var(--mk-shadow);
}

html.yh-theme-miku-star .DiscussionHero-title {
	color: var(--mk-teal-deep) !important;
	font-size: 22px !important;
	font-weight: 800 !important;
	text-shadow: 0 1px 0 rgba(255, 255, 255, 0.8);
}

html.yh-theme-miku-star .PostStream-item,
html.yh-theme-miku-star .Post {
	border: 1px solid rgba(57, 197, 187, 0.16);
	background: var(--mk-glass-strong);
	margin-bottom: 14px;
	padding: 14px 16px;
	border-radius: var(--mk-radius);
	box-shadow: 0 8px 24px rgba(57, 197, 187, 0.08);
	backdrop-filter: blur(8px);
	-webkit-backdrop-filter: blur(8px);
}

html.yh-theme-miku-star .Post-header {
	margin: -14px -16px 12px;
	padding: 10px 16px;
	background: linear-gradient(90deg, rgba(57, 197, 187, 0.12), rgba(255, 142, 200, 0.08));
	border-bottom: 1px solid rgba(57, 197, 187, 0.12);
	border-radius: var(--mk-radius) var(--mk-radius) 0 0;
	color: var(--mk-ink-soft) !important;
}

html.yh-theme-miku-star .PostUser-name a {
	color: var(--mk-teal-deep) !important;
	font-weight: 700;
}

html.yh-theme-miku-star .Post-body blockquote {
	background: rgba(212, 255, 246, 0.45) !important;
	border: 1px solid rgba(57, 197, 187, 0.2) !important;
	border-left: 4px solid var(--mk-teal) !important;
	border-radius: 0 12px 12px 0 !important;
	color: var(--mk-ink-soft) !important;
}

html.yh-theme-miku-star .Post-body pre,
html.yh-theme-miku-star .Post-body code {
	border-radius: 8px !important;
	border: 1px solid rgba(57, 197, 187, 0.18) !important;
	background: rgba(232, 255, 251, 0.65) !important;
}

html.yh-theme-miku-star .ReplyPlaceholder {
	border: 1px dashed rgba(57, 197, 187, 0.35);
	background: rgba(255, 255, 255, 0.7);
	border-radius: var(--mk-radius);
}

/* ---------- 5. 控件 ---------- */
html.yh-theme-miku-star .Button {
	border-radius: 999px !important;
	border: 1px solid rgba(57, 197, 187, 0.28) !important;
	background: linear-gradient(180deg, #ffffff 0%, #f0fffc 100%) !important;
	color: var(--mk-ink) !important;
	font-family: var(--mk-font);
	box-shadow: 0 2px 0 rgba(255, 255, 255, 0.9) inset, 0 4px 12px rgba(57, 197, 187, 0.1) !important;
	transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s ease;
}

html.yh-theme-miku-star .Button:hover {
	border-color: rgba(255, 142, 200, 0.55) !important;
	background: linear-gradient(180deg, #ffffff 0%, #ffe8f5 100%) !important;
	transform: translateY(-1px);
	box-shadow: 0 8px 18px rgba(255, 142, 200, 0.18) !important;
}

html.yh-theme-miku-star .Button:active,
html.yh-theme-miku-star .Button.active,
html.yh-theme-miku-star .open > .Dropdown-toggle.Button {
	transform: translateY(0);
	background: linear-gradient(180deg, #d4fff6, #e8fffb) !important;
	box-shadow: inset 0 2px 6px rgba(57, 197, 187, 0.2) !important;
}

html.yh-theme-miku-star .Button--primary {
	border-color: transparent !important;
	background: linear-gradient(135deg, #4fd4cb 0%, #39c5bb 45%, #2eb0c9 100%) !important;
	color: #fff !important;
	text-shadow: 0 1px 1px rgba(0, 0, 0, 0.15);
	box-shadow: 0 8px 20px rgba(57, 197, 187, 0.32) !important;
}

html.yh-theme-miku-star .Button--primary:hover {
	background: linear-gradient(135deg, #7fe0d8 0%, #4fd4cb 40%, #39c5bb 100%) !important;
	filter: brightness(1.03);
}

html.yh-theme-miku-star .Button--flat {
	border-color: transparent !important;
	background: transparent !important;
	box-shadow: none !important;
}

html.yh-theme-miku-star .Button--flat:hover {
	border-color: rgba(57, 197, 187, 0.25) !important;
	background: rgba(57, 197, 187, 0.1) !important;
}

html.yh-theme-miku-star .FormControl,
html.yh-theme-miku-star input[type="text"],
html.yh-theme-miku-star input[type="search"],
html.yh-theme-miku-star input[type="password"],
html.yh-theme-miku-star input[type="email"],
html.yh-theme-miku-star textarea,
html.yh-theme-miku-star select {
	border-radius: 12px !important;
	border: 1px solid rgba(57, 197, 187, 0.28) !important;
	background: rgba(255, 255, 255, 0.9) !important;
	color: var(--mk-ink) !important;
	box-shadow: inset 0 1px 2px rgba(57, 197, 187, 0.08) !important;
	font-family: var(--mk-font);
	transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

html.yh-theme-miku-star .FormControl:focus,
html.yh-theme-miku-star textarea:focus,
html.yh-theme-miku-star input:focus {
	border-color: var(--mk-teal) !important;
	outline: none !important;
	box-shadow:
		inset 0 1px 2px rgba(57, 197, 187, 0.08),
		0 0 0 3px rgba(57, 197, 187, 0.2) !important;
}

html.yh-theme-miku-star .Search-input .FormControl {
	border-radius: 999px !important;
	min-width: 160px;
	background: rgba(255, 255, 255, 0.75) !important;
}

html.yh-theme-miku-star .Dropdown-menu {
	border-radius: 14px !important;
	border: 1px solid rgba(57, 197, 187, 0.2) !important;
	background: rgba(255, 255, 255, 0.95) !important;
	backdrop-filter: blur(12px);
	-webkit-backdrop-filter: blur(12px);
	box-shadow: 0 16px 40px rgba(26, 58, 66, 0.16) !important;
	padding: 6px !important;
	overflow: hidden;
}

html.yh-theme-miku-star .App-header .Dropdown-menu {
	z-index: 1201;
	max-height: calc(100vh - var(--mk-header-h) - 12px);
	overflow-y: auto;
}

/* Flarum mounts the back button's slide-out discussion list outside the button. */
html.yh-theme-miku-star .DiscussionPage-list {
	z-index: 1150 !important;
}

html.yh-theme-miku-star .Dropdown-menu > li > a,
html.yh-theme-miku-star .Dropdown-menu > li > button {
	border-radius: 10px !important;
	color: var(--mk-ink) !important;
	font-family: var(--mk-font);
}

html.yh-theme-miku-star .Dropdown-menu > li > a:hover,
html.yh-theme-miku-star .Dropdown-menu > li > button:hover {
	background: linear-gradient(90deg, rgba(57, 197, 187, 0.16), rgba(255, 142, 200, 0.12)) !important;
	color: var(--mk-teal-deep) !important;
}

html.yh-theme-miku-star .Dropdown-header {
	color: var(--mk-teal-deep) !important;
	font-weight: 700;
}

html.yh-theme-miku-star .Dropdown-separator {
	background: rgba(57, 197, 187, 0.18) !important;
}

/* ---------- 6. 弹窗 / 回复框 ---------- */
html.yh-theme-miku-star .Modal-content {
	border-radius: 18px !important;
	border: 1px solid rgba(57, 197, 187, 0.25) !important;
	box-shadow: 0 24px 60px rgba(26, 58, 66, 0.22) !important;
	background: rgba(255, 255, 255, 0.95) !important;
	overflow: hidden;
	backdrop-filter: blur(16px);
	-webkit-backdrop-filter: blur(16px);
}

html.yh-theme-miku-star .Modal-header {
	background: linear-gradient(90deg, rgba(57, 197, 187, 0.18), rgba(255, 142, 200, 0.12)) !important;
	border: 0 !important;
	padding: 14px 18px !important;
}

html.yh-theme-miku-star .Modal-header h3 {
	color: var(--mk-teal-deep) !important;
	font-weight: 800 !important;
}

html.yh-theme-miku-star .Modal-body,
html.yh-theme-miku-star .Modal-footer {
	background: transparent !important;
	color: var(--mk-ink) !important;
}

html.yh-theme-miku-star .Alert {
	border-radius: 12px !important;
	border: 1px solid rgba(57, 197, 187, 0.22);
	backdrop-filter: blur(8px);
}

html.yh-theme-miku-star .Composer {
	border: 1px solid rgba(57, 197, 187, 0.28);
	border-radius: 18px 18px 0 0;
	box-shadow: 0 -12px 40px rgba(57, 197, 187, 0.18) !important;
	background: rgba(255, 255, 255, 0.94) !important;
	backdrop-filter: blur(14px);
	-webkit-backdrop-filter: blur(14px);
	overflow: hidden;
}

html.yh-theme-miku-star .Composer-header {
	margin: 0 !important;
	padding: 12px 16px !important;
	background:
		linear-gradient(90deg, rgba(57, 197, 187, 0.2), rgba(255, 142, 200, 0.14)),
		var(--mk-top, none) !important;
	background-size: auto, cover !important;
	background-position: 0 0, right center !important;
	color: var(--mk-teal-deep) !important;
	font-weight: 800 !important;
	border-bottom: 1px solid rgba(57, 197, 187, 0.15);
}

html.yh-theme-miku-star .Composer-header a,
html.yh-theme-miku-star .Composer-header h3 {
	color: var(--mk-teal-deep) !important;
}

html.yh-theme-miku-star .Composer-handle {
	background: linear-gradient(90deg, var(--mk-teal), var(--mk-pink), var(--mk-lavender)) !important;
	height: 4px !important;
}

html.yh-theme-miku-star .App-composer {
	left: calc(var(--mk-side-w) + 24px);
	right: 20px;
	z-index: 1500;
}

/* 默认桌面样式会再按原侧栏添加 Composer 外边距；这里改为与帖子主列共用宽度。 */
@media (min-width: 768px) {
	html.yh-theme-miku-star .Composer:not(.fullScreen) {
		max-width: 1120px;
		margin-left: auto !important;
		margin-right: auto !important;
	}
}

html.yh-theme-miku-star .AlertManager {
	z-index: 1600;
}

/* ---------- 7. 滚动条 ---------- */
html.yh-theme-miku-star,
html.yh-theme-miku-star * {
	scrollbar-color: #7fe0d8 #e8fffb;
}

html.yh-theme-miku-star::-webkit-scrollbar,
html.yh-theme-miku-star ::-webkit-scrollbar {
	width: 12px;
	height: 12px;
}

html.yh-theme-miku-star::-webkit-scrollbar-track,
html.yh-theme-miku-star ::-webkit-scrollbar-track {
	background: linear-gradient(90deg, #e8fffb, #fff5fb);
	border-left: 1px solid rgba(57, 197, 187, 0.12);
}

html.yh-theme-miku-star::-webkit-scrollbar-thumb,
html.yh-theme-miku-star ::-webkit-scrollbar-thumb {
	background: linear-gradient(180deg, #7fe0d8, #39c5bb 55%, #ff8ec8);
	border: 2px solid #e8fffb;
	border-radius: 999px;
}

html.yh-theme-miku-star::-webkit-scrollbar-thumb:hover,
html.yh-theme-miku-star ::-webkit-scrollbar-thumb:hover {
	background: linear-gradient(180deg, #9aefe8, #4fd4cb 50%, #ffb0d8);
}

/* ---------- 8. 链接与收尾 ---------- */
html.yh-theme-miku-star a {
	text-decoration: none;
	color: var(--link-color);
}

html.yh-theme-miku-star .App-content a:hover {
	color: var(--mk-pink);
	text-decoration: none;
}

html.yh-theme-miku-star #site-switcher-container {
	/* 不强制藏；若压到内容可在设置里再处理。这里只让它不那么抢戏 */
	filter: saturate(0.85);
}

html.yh-theme-miku-star .DiscussionList-loadMore {
	margin-top: 14px;
	text-align: center;
}

/* ---------- 9. 响应式 ---------- */
@media (max-width: 991.98px) {
	html.yh-theme-miku-star {
		--mk-side-w: 0px;
		--mk-banner-h: 132px;
	}

	html.yh-theme-miku-star .App-header .container {
		padding-left: 14px !important;
		padding-right: 14px !important;
	}

	html.yh-theme-miku-star .App-content {
		padding: calc(var(--mk-header-h) + 14px) 12px 28px !important;
	}

	html.yh-theme-miku-star .App-composer {
		left: 0;
		right: 0;
	}

	html.yh-theme-miku-star .sideNav,
	html.yh-theme-miku-star .IndexPage-nav.sideNav,
	html.yh-theme-miku-star .DiscussionPage-nav {
		position: relative !important;
		top: auto !important;
		left: auto !important;
		bottom: auto !important;
		width: auto !important;
		min-width: 0 !important;
		max-width: none !important;
		margin: 0 0 14px !important;
		padding: 12px !important;
		border-right: 0 !important;
		border-radius: var(--mk-radius) !important;
		box-shadow: var(--mk-shadow) !important;
		overflow: auto !important;
	}

	html.yh-theme-miku-star .sideNav::after,
	html.yh-theme-miku-star .IndexPage-nav.sideNav::after,
	html.yh-theme-miku-star .DiscussionPage-nav::after {
		display: none !important;
	}

	html.yh-theme-miku-star .sideNav > ul > li,
	html.yh-theme-miku-star .sideNav .Dropdown-menu > li {
		display: inline-block !important;
		width: auto !important;
		margin: 0 8px 8px 0 !important;
	}

	html.yh-theme-miku-star .item-newDiscussion .Button,
	html.yh-theme-miku-star .sideNav .item-newDiscussion .Button {
		width: auto;
	}
}

@media (max-width: 767.98px) {
	html.yh-theme-miku-star {
		--mk-header-h: 52px;
	}

	html.yh-theme-miku-star .Hero .container {
		padding: 20px 18px !important;
	}

	html.yh-theme-miku-star body {
		background-position: 70% center;
	}
}

@media (prefers-reduced-motion: reduce) {
	html.yh-theme-miku-star .Button,
	html.yh-theme-miku-star .DiscussionListItem,
	html.yh-theme-miku-star .sideNav .Dropdown-menu > li > a {
		transition: none !important;
	}
}
